{
  "id": 30,
  "knowledge": "Scan Time Efficiency (STE)",
  "description": "Measures how efficiently scanning time was used relative to data quality and completeness metrics.",
  "definition": "STE = \\frac{SQS \\times \\sqrt{CoverPct}}{SpanMin \\times \\sqrt{ScanCount}}, \\text{ where SQS is the Scan Quality Score and higher STE values indicate more efficient use of scanning time relative to coverage achieved.}"
}

{
  "id": 33,
  "knowledge": "Registration Accuracy Ratio (RAR)",
  "description": "Evaluates registration accuracy relative to scan resolution using propagation of uncertainty principles.",
  "definition": "RAR = \\frac{ScanResolMm}{LogAccuMm \\times \\sqrt{1 + \\frac{ErrValMm}{LogAccuMm}}}, \\text{ where values > 1 indicate registration accuracy exceeds scan resolution, a desirable outcome for precise spatial analysis.}"
}

{
  "id": 34,
  "knowledge": "Spatial Density Index (SDI)",
  "description": "Assesses point cloud density relative to site dimensions for spatial sampling adequacy.",
  "definition": "SDI = \\frac{TotalPts}{AreaM2 \\times 10^4} \\times \\left(\\frac{PointDense}{CloudDense}\\right)^{0.5}"
}

{
  "id": 35,
  "knowledge": "Conservation Priority Index (CPI)",
  "description": "Quantifies the urgency of conservation efforts based on site condition, historical significance and structural stability.",
  "definition": "CPI = \\begin{cases} 100 - PS + AF \\times \\left(1 + \\frac{TS}{10}\\right), & \\text{if in a Degradation Risk Zone} \\\\ 50 - PS + AF \\times \\left(1 + \\frac{TS}{20}\\right), & \\text{otherwise} \\end{cases}, \\text{ where PS is 0-100 based on PresStat condition ('Excellent'=10, 'Good'=30, 'Fair'=50, 'Poor'=70, 'Critical'=90), AF is approximate age in millennia derived from GuessDate, and TS is 0-10 based on TypeSite rarity.}"
}

{
  "id": 36,
  "knowledge": "Mesh-to-Point Ratio (MPR)",
  "description": "Evaluates the efficiency of mesh generation from point cloud data for optimal decimation determination.",
  "definition": "MPR = \\frac{FacetVerts}{TotalPts} \\times 100 \\times \\left(\\frac{MCR}{10}\\right)^{0.3}, \\text{ where MCR is the Mesh Complexity Ratio and values around 25-30 indicate optimal decimation for archaeological purposes with appropriate feature preservation.}"
}

{
  "id": 37,
  "knowledge": "Processing Resource Utilization (PRU)",
  "description": "Measures the efficiency of computing resource utilization during scan processing relative to data complexity.",
  "definition": "PRU = \\frac{FlowHrs \\times (ProcCPU + ProcGPU) / 2}{GBSize \\times 10 \\times \\log_{10}(FacetVerts + 10^4)}, \\text{ where lower values indicate more efficient use of computing resources relative to mesh complexity.}"
}

{
  "id": 38,
  "knowledge": "Digital Preservation Quality (DPQ)",
  "description": "Comprehensive metric for evaluating digital preservation quality for archaeological sites with weighted quality factors.",
  "definition": "DPQ = (0.3 \\times ADC) + (0.3 \\times MFS) + (0.2 \\times RAR) + (0.2 \\times SCE) - 2 \\times \\sqrt{\\frac{ErrValMm}{ScanResolMm}}, \\text{ where ADC is Archaeological Documentation Completeness, MFS is Model Fidelity Score, RAR is Registration Accuracy Ratio, and SCE is Scan Coverage Effectiveness.}"
}

{
  "id": 39,
  "knowledge": "Equipment Effectiveness Ratio (EER)",
  "description": "Evaluates how effectively equipment was utilized based on power consumption and scan quality relative to equipment capability.",
  "definition": "EER = \\frac{SQS \\times EquipStatus\\_value}{PowerLevel \\times (101 - EquipAge\\_days) / 365} \\times 25, \\text{ where SQS is the Scan Quality Score, EquipStatus_value is 1.0 for 'Excellent' to 0.2 for 'Poor', and EquipAge_days is days since EquipTune, with higher values indicating more efficient use of equipment relative to condition.}"
}

